1	//! Nested logical configuration: all source/evaluation/binding work is worker-owned.
2	use flux_config::{Config, ConfigCoordinator, HelperLimits};
3	use flux_input::{BindingSet, UnmappedPolicy};
4	use std::{
5	    path::PathBuf,
6	    sync::{Arc, Condvar, Mutex},
7	    thread::JoinHandle,
8	};
9	use xkbcommon::xkb;
10	
11	type Failure = &'static str;
12	struct Prepared {
13	    desired: Config,
14	    bindings: BindingSet,
15	}
16	// Retired tables, schema strings and layout storage are destroyed on the worker.
17	struct Retired {
18	    _desired: Option<Config>,
19	    _bindings: Option<BindingSet>,
20	    _layout: Option<flux_layout::Layout>,
21	}
22	#[derive(Default)]
23	struct Control {
24	    latest: u64,
25	    pending: Option<(u64, PathBuf)>,
26	    evaluation_ready: bool,
27	    completion: Option<(u64, Result<Prepared, Failure>)>,
28	    retired: Option<Retired>,
29	    closed: bool,
30	}
31	#[derive(Default)]
32	struct Shared {
33	    control: Mutex<Control>,
34	    changed: Condvar,
35	}
36	pub struct RuntimeConfig {
37	    source: PathBuf,
38	    shared: Arc<Shared>,
39	    worker: Option<JoinHandle<()>>,
40	    desired: Option<Config>,
41	    applied: Option<u64>,
42	    status: &'static str,
43	    last_error: Option<Failure>,
44	}
45	impl RuntimeConfig {
46	    fn new(
47	        source: PathBuf,
48	        helper: PathBuf,
49	        keymap: String,
50	        ping: calloop::ping::Ping,
51	    ) -> std::io::Result<Self> {
52	        let shared = Arc::new(Shared::default());
53	        let notified = shared.clone();
54	        let coordinator = ConfigCoordinator::new(helper, HelperLimits::default(), move || {
55	            notified
56	                .control
57	                .lock()
58	                .unwrap_or_else(|e| e.into_inner())
59	                .evaluation_ready = true;
60	            notified.changed.notify_one();
61	        })?;
62	        let control = shared.clone();
63	        let worker = std::thread::Builder::new()
64	            .name("flux-config-prepare".into())
65	            .spawn(move || run_worker(control, coordinator, keymap, ping))?;
66	        Ok(Self {
67	            source,
68	            shared,
69	            worker: Some(worker),
70	            desired: None,
71	            applied: None,
72	            status: "pending",
73	            last_error: None,
74	        })
75	    }
76	    fn request(&mut self) -> Result<u64, Failure> {
77	        let mut c = self
78	            .shared
79	            .control
80	            .lock()
81	            .unwrap_or_else(|e| e.into_inner());
82	        if c.closed || self.worker.as_ref().is_none_or(|w| w.is_finished()) {
83	            return Err("configuration worker is unavailable");
84	        }
85	        let generation = c
86	            .latest
87	            .checked_add(1)
88	            .ok_or("configuration generation exhausted")?;
89	        c.latest = generation;
90	        // Only a bounded path is replaced here. Old large completions stay on
91	        // the worker until it observes the superseding request.
92	        c.pending = Some((generation, self.source.clone()));
93	        self.status = "pending";
94	        self.last_error = None;
95	        self.shared.changed.notify_one();
96	        Ok(generation)
97	    }
98	    fn completion(&mut self) -> Option<(u64, Result<Prepared, Failure>)> {
99	        let mut c = self
100	            .shared
101	            .control
102	            .lock()
103	            .unwrap_or_else(|e| e.into_inner());
104	        if self.status != "failed" && self.worker.as_ref().is_none_or(|w| w.is_finished()) {
105	            return Some((c.latest, Err("configuration preparation worker stopped")));
106	        }
107	        if c.retired.is_some() || c.completion.as_ref()?.0 != c.latest {
108	            return None;
109	        }
110	        c.completion.take()
111	    }
112	    fn retire(&self, value: Retired) {
113	        let mut c = self
114	            .shared
115	            .control
116	            .lock()
117	            .unwrap_or_else(|e| e.into_inner());
118	        // Only dispatch fills this slot, immediately after taking a completion
119	        // which checked it empty. The worker can only empty it in between.
120	        assert!(c.retired.is_none());
121	        c.retired = Some(value);
122	        self.shared.changed.notify_one();
123	    }
124	    pub fn shutdown(&mut self) -> std::io::Result<()> {
125	        {
126	            let mut c = self
127	                .shared
128	                .control
129	                .lock()
130	                .unwrap_or_else(|e| e.into_inner());
131	            c.closed = true;
132	            self.shared.changed.notify_one();
133	        }
134	        if let Some(worker) = self.worker.take() {
135	            worker
136	                .join()
137	                .map_err(|_| std::io::Error::other("configuration preparation worker panicked"))?;
138	        }
139	        Ok(())
140	    }
141	    pub fn diagnostics(&self) -> serde_json::Value {
142	        let c = self
143	            .shared
144	            .control
145	            .lock()
146	            .unwrap_or_else(|e| e.into_inner());
147	        serde_json::json!({
148	            "requested_generation":(c.latest != 0).then(||c.latest.to_string()),
149	            "applied_generation":self.applied.map(|g|g.to_string()),
150	            "prepared_generation":c.completion.as_ref().filter(|(g,r)|*g == c.latest && r.is_ok()).map(|(g,_)|g.to_string()),
151	            "status":self.status, "last_error":self.last_error,
152	        })
153	    }
154	    pub fn applied(&self) -> bool {
155	        self.applied.is_some()
156	    }
157	}
158	impl Drop for RuntimeConfig {
159	    fn drop(&mut self) {
160	        let _ = self.shutdown();
161	    }
162	}
163	fn run_worker(
164	    shared: Arc<Shared>,
165	    mut coordinator: ConfigCoordinator,
166	    keymap: String,
167	    ping: calloop::ping::Ping,
168	) {
169	    let context = xkb::Context::new(xkb::CONTEXT_NO_ENVIRONMENT_NAMES);
170	    let map = xkb::Keymap::new_from_string(
171	        &context,
172	        keymap,
173	        xkb::KEYMAP_FORMAT_TEXT_V1,
174	        xkb::KEYMAP_COMPILE_NO_FLAGS,
175	    );
176	    let mut active = None;
177	    loop {
178	        let (job, retired, ready) = {
179	            let mut c = shared.control.lock().unwrap_or_else(|e| e.into_inner());
180	            while !c.closed && c.pending.is_none() && c.retired.is_none() && !c.evaluation_ready {
181	                c = shared.changed.wait(c).unwrap_or_else(|e| e.into_inner());
182	            }
183	            if c.closed {
184	                break;
185	            }
186	            let values = (c.pending.take(), c.retired.take(), c.evaluation_ready);
187	            c.evaluation_ready = false;
188	            values
189	        };
190	        let retired_any = retired.is_some();
191	        drop(retired);
192	        if retired_any {
193	            ping.ping();
194	        }
195	        if let Some((generation, path)) = job {
196	            // Move stale completions out before dropping them off dispatch.
197	            let old = shared
198	                .control
199	                .lock()
200	                .unwrap_or_else(|e| e.into_inner())
201	                .completion
202	                .take();
203	            drop(old);
204	            match coordinator.request_path(path) {
205	                Ok(inner) => active = Some((generation, inner)),
206	                Err(_) => publish(
207	                    &shared,
208	                    generation,
209	                    Err("configuration request could not be admitted"),
210	                    &ping,
211	                ),
212	            }
213	        }
214	        if ready
215	            && let Some(result) = coordinator.take_completion()
216	            && let Some((generation, inner)) = active
217	            && inner == result.generation
218	        {
219	            let result = result
220	                .result
221	                .map_err(|failure| match failure.kind {
222	                    flux_config::ConfigFailureKind::Io => {
223	                        "configuration source or helper I/O failed"
224	                    }
225	                    flux_config::ConfigFailureKind::Invalid => {
226	                        "configuration schema or source validation failed"
227	                    }
228	                    flux_config::ConfigFailureKind::Timeout => "configuration evaluation timed out",
229	                    flux_config::ConfigFailureKind::Helper => {
230	                        "configuration helper rejected evaluation"
231	                    }
232	                    flux_config::ConfigFailureKind::Cancelled => {
233	                        "configuration evaluation cancelled"
234	                    }
235	                })
236	                .and_then(|candidate| {
237	                    let config = &candidate.config().config;
238	                    if config.layout.gaps > 1024.0 {
239	                        return Err("layout.gaps exceeds the nested model limit of 1024");
240	                    }
241	                    if config.bindings.iter().any(|b| {
242	                        matches!(
243	                            b.action,
244	                            flux_core::Action::Fullscreen { .. }
245	                                | flux_core::Action::Floating { .. }
246	                                | flux_core::Action::Overview { .. }
247	                                | flux_core::Action::Lock
248	                        )
249	                    }) {
250	                        return Err("a binding action is unavailable in the nested backend");
251	                    }
252	                    let bindings = BindingSet::compile(
253	                        &config.bindings,
254	                        map.as_ref()
255	                            .ok_or("seat keymap could not be reconstructed")?,
256	                        UnmappedPolicy::Reject,
257	                    )
258	                    .map_err(|_| "configuration bindings failed seat-keymap validation")?;
259	                    Ok(Prepared {
260	                        desired: config.clone(),
261	                        bindings,
262	                    })
263	                });
264	            publish(&shared, generation, result, &ping);
265	        }
266	    }
267	    // No join or large source/schema/table destruction runs during dispatch.
268	    let _ = coordinator.shutdown();
269	    let mut c = shared.control.lock().unwrap_or_else(|e| e.into_inner());
270	    c.pending = None;
271	    c.completion = None;
272	    c.retired = None;
273	}
274	fn publish(
275	    shared: &Shared,
276	    generation: u64,
277	    value: Result<Prepared, Failure>,
278	    ping: &calloop::ping::Ping,
279	) {
280	    let old = {
281	        let mut c = shared.control.lock().unwrap_or_else(|e| e.into_inner());
282	        if c.closed || c.latest != generation {
283	            return;
284	        }
285	        c.completion.replace((generation, value))
286	    };
287	    drop(old);
288	    ping.ping();
289	}
