291	impl crate::Fluxwm {
292	    pub fn init_config(
293	        &mut self,
294	        handle: &calloop::LoopHandle<'static, Self>,
295	        source: Option<PathBuf>,
296	        helper: PathBuf,
297	    ) -> std::io::Result<()> {
298	        let Some(source) = source else {
299	            return Ok(());
300	        };
301	        let (ping, events) = calloop::ping::make_ping()?;
302	        handle
303	            .insert_source(events, |(), _, _| {})
304	            .map_err(|e| std::io::Error::other(e.to_string()))?;
305	        let keyboard = self.seat.get_keyboard().expect("startup seat has keyboard");
306	        let keymap = keyboard.with_xkb_state(self, |context| {
307	            let xkb = context.xkb().lock().unwrap();
308	            // SAFETY: string serialization borrows only under this Xkb lock;
309	            // the worker receives owned bytes and creates its own native map.
310	            unsafe { xkb.keymap() }.get_as_string(xkb::KEYMAP_FORMAT_TEXT_V1)
311	        });
312	        let mut config = RuntimeConfig::new(source, helper, keymap, ping)?;
313	        config.request().map_err(std::io::Error::other)?;
314	        self.config = Some(config);
315	        Ok(())
316	    }
317	    pub fn request_config_reload(&mut self) -> Result<u64, Failure> {
318	        if self.stopping || self.shutdown_deadline.is_some() {
319	            return Err("instance is shutting down");
320	        }
321	        self.config
322	            .as_mut()
323	            .ok_or("configuration loading is disabled")?
324	            .request()
325	    }
326	    pub fn drive_config(&mut self) {
327	        if self.stopping
328	            || self.shutdown_deadline.is_some()
329	            || self
330	                .seat
331	                .get_keyboard()
332	                .is_some_and(|k| !k.pressed_keys().is_empty() || k.is_grabbed())
333	            || self.seat.get_pointer().is_some_and(|p| p.is_grabbed())
334	            || !self.pointer_presses.is_empty()
335	        {
336	            return;
337	        }
338	        let Some(mut config) = self.config.take() else {
339	            return;
340	        };
341	        if let Some((generation, result)) = config.completion() {
342	            match result {
343	                Err(error) => {
344	                    config.status = "failed";
345	                    config.last_error = Some(error);
346	                    self.bump_sequence();
347	                }
348	                Ok(prepared) => {
349	                    let mut layout = self.layout.clone();
350	                    if layout
351	                        .reconfigure(prepared.desired.layout.gaps, prepared.desired.layout.mode)
352	                        .is_err()
353	                    {
354	                        config.status = "failed";
355	                        config.last_error =
356	                            Some("configuration layout would invalidate live geometry");
357	                        config.retire(Retired {
358	                            _desired: Some(prepared.desired),
359	                            _bindings: Some(prepared.bindings),
360	                            _layout: Some(layout),
361	                        });
362	                    } else if self.sequence == u64::MAX {
363	                        config.status = "failed";
364	                        config.last_error = Some("state sequence exhausted");
365	                        config.retire(Retired {
366	                            _desired: Some(prepared.desired),
367	                            _bindings: Some(prepared.bindings),
368	                            _layout: Some(layout),
369	                        });
370	                    } else {
371	                        let old = Retired {
372	                            _desired: config.desired.replace(prepared.desired),
373	                            _bindings: Some(std::mem::replace(
374	                                &mut self.bindings,
375	                                prepared.bindings,
376	                            )),
377	                            _layout: Some(std::mem::replace(&mut self.layout, layout)),
378	                        };
379	                        config.applied = Some(generation);
380	                        config.status = "applied";
381	                        config.last_error = None;
382	                        config.retire(old);
383	                        self.relayout();
384	                        self.restore_keyboard_focus();
385	                    }
386	                    self.bump_sequence();
387	                }
388	            }
389	        }
390	        self.config = Some(config);
391	    }
392	    pub fn effective_config(&self) -> serde_json::Value {
393	        let config = self.config.as_ref();
394	        serde_json::json!({
395	            "generation":config.and_then(|c|c.applied).map(|g|g.to_string()),
396	            "desired":config.and_then(|c|c.desired.as_ref()).map(|c|serde_json::json!({"layout":{"gaps":c.layout.gaps,"mode":c.layout.mode},"binding_entries":c.bindings.len()})),
397	            "effective":{"layout":{"gaps":self.layout.gap(),"mode":self.layout.mode()},"binding_entries":self.bindings.len(),"keymap":"startup-seat-keymap"},
398	            "unsupported":["layout.outer_gap","layout.width_presets","layout.default_width","layout.focus_margin","layout.canvas","input","outputs","animations","decoration","rules","autostart","security"],
399	        })
400	    }
401	}
