404	mod tests {
405	    use super::*;
406	    #[test]
407	    fn termination_seals_ready_config_publication() {
408	        const GUARD: &str = "FLUX_TEST_CONFIG_STOP_CHILD";
409	        if std::env::var_os(GUARD).as_deref() != Some(std::ffi::OsStr::new("1")) {
410	            let dir = tempfile::Builder::new()
411	                .prefix("fc-stop-")
412	                .tempdir()
413	                .unwrap();
414	            let log_path = dir.path().join("child.log");
415	            let output = std::fs::File::create(&log_path).unwrap();
416	            let mut child = std::process::Command::new(std::env::current_exe().unwrap())
417	                .args([
418	                    "--exact",
419	                    "config::tests::termination_seals_ready_config_publication",
420	                    "--nocapture",
421	                ])
422	                .env(GUARD, "1")
423	                .env("XDG_RUNTIME_DIR", dir.path())
424	                .stdout(output.try_clone().unwrap())
425	                .stderr(output)
426	                .spawn()
427	                .unwrap();
428	            let deadline = std::time::Instant::now() + std::time::Duration::from_secs(5);
429	            let status = loop {
430	                if let Some(status) = child.try_wait().unwrap() {
431	                    break status;
432	                }
433	                if std::time::Instant::now() >= deadline {
434	                    let _ = child.kill();
435	                    let _ = child.wait();
436	                    panic!("owned config-stop child exceeded deadline");
437	                }
438	                std::thread::sleep(std::time::Duration::from_millis(5));
439	            };
440	            assert!(
441	                status.success(),
442	                "{}",
443	                std::fs::read_to_string(log_path).unwrap()
444	            );
445	            return;
446	        }
447	        let mut event_loop = calloop::EventLoop::try_new().unwrap();
448	        let display = smithay::reexports::wayland_server::Display::new().unwrap();
449	        let mut state = crate::Fluxwm::new(&mut event_loop, display, "stop-test").unwrap();
450	        let keyboard = state.seat.get_keyboard().unwrap();
451	        let desired = Config::default();
452	        let bindings = keyboard.with_xkb_state(&mut state, |context| {
453	            let xkb = context.xkb().lock().unwrap();
454	            // SAFETY: compilation borrows this map only under the native lock.
455	            BindingSet::compile(
456	                &desired.bindings,
457	                unsafe { xkb.keymap() },
458	                UnmappedPolicy::Reject,
459	            )
460	            .unwrap()
461	        });
462	        let shared = Arc::new(Shared::default());
463	        {
464	            let mut c = shared.control.lock().unwrap();
465	            c.latest = 1;
466	            c.completion = Some((1, Ok(Prepared { desired, bindings })));
467	        }
468	        // A live owned test worker avoids the stopped-worker fallback masking
469	        // removal of the actual publication gate. It does not evaluate Lua.
470	        let worker_shared = shared.clone();
471	        let worker = std::thread::spawn(move || {
472	            let mut c = worker_shared.control.lock().unwrap();
473	            while !c.closed {
474	                c = worker_shared.changed.wait(c).unwrap();
475	            }
476	        });
477	        state.config = Some(RuntimeConfig {
478	            source: "/unused".into(),
479	            shared,
480	            worker: Some(worker),
481	            desired: None,
482	            applied: None,
483	            status: "pending",
484	            last_error: None,
485	        });
486	        let before = state.effective_config();
487	        let before_sequence = state.sequence;
488	        assert!(
489	            !state
490	                .config
491	                .as_ref()
492	                .unwrap()
493	                .worker
494	                .as_ref()
495	                .unwrap()
496	                .is_finished()
497	        );
498	        state.stop(); // same sealing method as SIGTERM, timer, host-close and fail
499	        state.finish_dispatch();
500	        state.finish_dispatch(); // main's final dispatch cannot publish either
501	        assert_eq!(state.effective_config(), before);
502	        assert_eq!(state.config.as_ref().unwrap().applied, None);
503	        assert_eq!(state.sequence, before_sequence);
504	        assert!(state.request_config_reload().is_err());
505	        assert!(
506	            state
507	                .apply_action(flux_core::Action::WorkspaceMode {
508	                    mode: flux_core::LayoutMode::Canvas
509	                })
510	                .is_err()
511	        );
512	        state.config.as_mut().unwrap().shutdown().unwrap();
513	    }
514	}
