/// An evaluated value, not an applied configuration. Intentionally not Clone.
#[derive(Debug)]
pub struct ConfigCandidate {
    generation: ConfigGeneration,
    owner: Weak<Shared>,
    config: Arc<CompiledConfig>,
}
impl ConfigCandidate {
    pub fn generation(&self) -> ConfigGeneration {
        self.generation
    }
    pub fn config(&self) -> &CompiledConfig {
        &self.config
    }
}
#[derive(Debug)]
pub struct ConfigEvaluation {
    pub generation: ConfigGeneration,
    pub result: Result<ConfigCandidate, ConfigEvaluationFailure>,
}
#[derive(Debug, Clone, Copy)]
pub struct ConfigCoordinatorStatus {
    pub latest: Option<ConfigGeneration>,
    pub active: Option<ConfigGeneration>,
    pub pending: Option<ConfigGeneration>,
    /// Observation only; signalling uses the supervisor's unreaped Child handle.
    pub active_helper_pid: Option<u32>,
    pub completion_ready: bool,
    pub closed: bool,
}
#[derive(Debug)]
enum Source {
    Snapshot(Vec<u8>),
    Path(PathBuf),
}
impl Source {
    fn acquire(self, cancelled: &AtomicBool) -> crate::Result<Vec<u8>> {
        if cancelled.load(Ordering::Acquire) {
            return Err(ConfigError::Cancelled);
        }
        let acquired = match self {
            Self::Snapshot(bytes) => Ok(bytes),
            Self::Path(path) => read_source_file(path),
        };
        if cancelled.load(Ordering::Acquire) {
            return Err(ConfigError::Cancelled);
        }
        let bytes = acquired?;
        if bytes.len() > MAX_SOURCE_BYTES {
            return Err(crate::invalid("configuration source exceeds byte bound"));
        }
        std::str::from_utf8(&bytes)
            .map_err(|_| crate::invalid("configuration source is not UTF-8"))?;
        Ok(bytes)
    }
}
#[cfg(target_os = "linux")]
fn read_source_file(path: PathBuf) -> crate::Result<Vec<u8>> {
    use std::{fs::OpenOptions, io::Read, os::unix::fs::OpenOptionsExt};
    // Symlinks are deliberately followed. Validate the opened descriptor, so a
    // path replaced between admission and open cannot bypass the regular-file check.
    let file = OpenOptions::new()
        .read(true)
        .custom_flags(libc::O_NONBLOCK | libc::O_CLOEXEC)
        .open(path)?;
    let metadata = file.metadata()?;
    if !metadata.is_file() {
        return Err(crate::invalid("configuration source is not a regular file"));
    }
    if metadata.len() > MAX_SOURCE_BYTES as u64 {
        return Err(crate::invalid("configuration source exceeds byte bound"));
    }
    let mut bytes = Vec::new();
    file.take((MAX_SOURCE_BYTES + 1) as u64)
        .read_to_end(&mut bytes)?;
    Ok(bytes)
}
#[cfg(not(target_os = "linux"))]
fn read_source_file(_path: PathBuf) -> crate::Result<Vec<u8>> {
    Err(crate::invalid(
        "configuration file acquisition is qualified only for Linux",
    ))
}
#[derive(Debug)]
struct Job {
    generation: ConfigGeneration,
    source: Source,
}
#[derive(Debug, Default)]
struct State {
    latest: u64,
    active: Option<ConfigGeneration>,
    active_helper_pid: Option<u32>,
    pending: Option<Job>,
    completion: Option<ConfigEvaluation>,
    closed: bool,
}
#[derive(Debug, Default)]
struct Shared {
    state: Mutex<State>,
    changed: Condvar,
    cancelled: AtomicBool,
}

/// One worker, one active evaluation, one replaceable pending source, and one
/// completion slot. All public mutation needs exclusive caller ownership.
///
/// `notify` runs on the worker, outside the mutex, and must be nonblocking and
/// nonpanicking (for example a coalesced event-loop ping). Notifications are hints:
/// stale work may already have been superseded before the caller handles a wake.
/// File acquisition and evaluation run on the worker, with no event-loop dependency.
/// Call shutdown/Drop outside compositor dispatch: joining, exec and kill/wait have
/// no universal wall-clock bound under kernel/filesystem failure.
pub struct ConfigCoordinator {
    shared: Arc<Shared>,
    worker: Option<JoinHandle<()>>,
    last_good: Option<Arc<CompiledConfig>>,
}
impl ConfigCoordinator {
    pub fn new(
        helper: PathBuf,
        limits: HelperLimits,
        notify: impl Fn() + Send + 'static,
    ) -> std::io::Result<Self> {
        let shared = Arc::new(Shared::default());
        let worker_shared = shared.clone();
        let worker = thread::Builder::new()
            .name("flux-config".into())
            .spawn(move || {
                loop {
                    let job = {
                        let mut state = worker_shared
                            .state
                            .lock()
                            .unwrap_or_else(|e| e.into_inner());
                        while !state.closed && state.pending.is_none() {
                            state = worker_shared
                                .changed
                                .wait(state)
                                .unwrap_or_else(|e| e.into_inner());
