229	    command: &std::ffi::OsStr,
230	    args: &[OsString],
231	    socket: &std::ffi::OsStr,
232	    ipc: Option<&std::path::Path>,
233	) -> std::io::Result<Child> {
234	    use std::os::unix::process::CommandExt;
235	    let mut command = Command::new(command);
