243	    } else {
244	        command.env_remove("FLUXWM_SOCKET");
245	    }
246	    // SAFETY: child-only closure uses async-signal-safe signal-mask operations,
247	    // with no allocator/locks. Undo only masks installed by this executable.
248	    unsafe {
249	        command.pre_exec(|| {
250	            let mut signals: libc::sigset_t = std::mem::zeroed();
251	            libc::sigemptyset(&mut signals);
252	            libc::sigaddset(&mut signals, libc::SIGTERM);
253	            libc::sigaddset(&mut signals, libc::SIGINT);
254	            libc::sigaddset(&mut signals, libc::SIGCHLD);
255	            let error = libc::pthread_sigmask(libc::SIG_UNBLOCK, &signals, std::ptr::null_mut());
256	            if error == 0 {
257	                Ok(())
258	            } else {
259	                Err(std::io::Error::from_raw_os_error(error))
260	            }
261	        });
262	    }
263	    command.spawn()
